<?php
$pageTitle='Dashboard';
require_once __DIR__.'/includes/header.php';
require_once __DIR__.'/includes/sidebar.php';
$db=getDB();$club=$_SESSION['club_id'];
$today=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM sessions WHERE club_id=? AND status='completed' AND DATE(end_time)=CURDATE()");$today->execute([$club]);$revenue=(float)$today->fetchColumn();
$active=$db->prepare("SELECT COUNT(*) FROM sessions WHERE club_id=? AND status IN ('running','paused')");$active->execute([$club]);$activeSessions=(int)$active->fetchColumn();
$expensesQ=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE club_id=? AND expense_date=CURDATE()');$expensesQ->execute([$club]);$expenses=(float)$expensesQ->fetchColumn();
$playersQ=$db->prepare('SELECT COUNT(*) FROM players WHERE club_id=? AND is_active=1');$playersQ->execute([$club]);$players=(int)$playersQ->fetchColumn();
$month=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM sessions WHERE club_id=? AND status='completed' AND DATE_FORMAT(end_time,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m')");$month->execute([$club]);$monthly=(float)$month->fetchColumn();
$cafeQ=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM cafe_orders WHERE club_id=? AND status='completed' AND DATE(created_at)=CURDATE()");$cafeQ->execute([$club]);$cafe=(float)$cafeQ->fetchColumn();
$daily=$db->prepare("SELECT DATE(end_time) d,SUM(total_amount) total FROM sessions WHERE club_id=? AND status='completed' AND end_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) GROUP BY DATE(end_time) ORDER BY d");$daily->execute([$club]);$chart=$daily->fetchAll();
?>
<div class="page-header"><div><p class="page-kicker">Owner overview</p><h1 class="page-title">Good day, <?=sanitize(explode(' ',$_SESSION['user_name'])[0])?>.</h1><p class="page-description">Your live snapshot of tables, revenue and club activity for <?=date('l, j F')?>.</p></div><a href="<?=url('operator.php')?>" class="btn-primary"><i class="fa-solid fa-table-cells-large"></i> Open live floor</a></div>
<div class="grid grid-cols-2 xl:grid-cols-4 gap-4"><article class="card metric-card"><p class="metric-label">Today’s revenue</p><p class="metric-value text-green-300"><?=money($revenue)?></p><p class="metric-note"><i class="fa-solid fa-arrow-trend-up text-green-400"></i> Completed table sessions</p></article><article class="card metric-card"><p class="metric-label">Active tables</p><p class="metric-value text-red-300"><?=$activeSessions?></p><p class="metric-note"><i class="fa-solid fa-circle text-[.42rem] text-red-400"></i> Running or paused right now</p></article><article class="card metric-card"><p class="metric-label">Today’s expenses</p><p class="metric-value text-orange-300"><?=money($expenses)?></p><p class="metric-note"><i class="fa-solid fa-receipt text-orange-300"></i> Recorded operating costs</p></article><article class="card metric-card"><p class="metric-label">Net position</p><p class="metric-value text-emerald-300"><?=money($revenue-$expenses)?></p><p class="metric-note"><i class="fa-solid fa-wallet text-emerald-300"></i> Revenue less today’s expenses</p></article></div>
<div class="grid md:grid-cols-3 gap-4 mt-4"><article class="card"><p class="metric-label">This month</p><p class="text-xl font-extrabold mt-2"><?=money($monthly)?></p><p class="metric-note">Completed session revenue</p></article><article class="card"><p class="metric-label">Active players</p><p class="text-xl font-extrabold mt-2"><?=$players?></p><p class="metric-note">Members and regular guests</p></article><article class="card"><p class="metric-label">Café sales today</p><p class="text-xl font-extrabold mt-2"><?=money($cafe)?></p><p class="metric-note">Completed café orders</p></article></div>
<div class="grid xl:grid-cols-5 gap-4 mt-5"><section class="card xl:col-span-3"><div class="panel-head"><div><h2 class="section-title">Revenue trend</h2><p class="section-subtitle">Completed session revenue across the last 30 days.</p></div><span class="soft-pill"><i class="fa-solid fa-chart-line text-green-300"></i> 30 days</span></div><div class="h-64"><canvas id="revenueChart"></canvas></div></section><section class="card xl:col-span-2"><div class="panel-head"><div><h2 class="section-title">Today’s mix</h2><p class="section-subtitle">Where today’s sales are coming from.</p></div></div><div class="h-64"><canvas id="sourceChart"></canvas></div></section></div>
