new Chart(document.getElementById('revenueChart'),{type:'line',data:{labels:<?=json_encode(array_column($chart,'d'))?>,datasets:[{label:'Revenue',data:<?=json_encode(array_map('floatval',array_column($chart,'total')))?>,borderColor:'#2ed68e',backgroundColor:'rgba(46,214,142,.12)',borderWidth:2,fill:true,tension:.38,pointRadius:0,pointHoverRadius:4}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{backgroundColor:'#101d2d',borderColor:'#263a51',borderWidth:1,titleColor:'#eff7f5',bodyColor:'#b9c9d1'}},scales:{x:{ticks:{color:chartText,maxTicksLimit:6},grid:{display:false},border:{display:false}},y:{ticks:{color:chartText},grid:{color:chartGrid},border:{display:false}}}}});
